use std::collections::BTreeMap;

use velnor_model::{AllTrigger, ChangeSet, RepoPath, RustSelection};
use velnor_render::seal;
use velnor_rust::select;

use crate::select::{all, path, two_roots, unknown};

const GENERATED_HEADER: &str =
    "# Generated by velnor-gen. Change .velnor/workflows.toml and run `velnor-gen generate`.\n";

fn sealed(body: &str) -> String {
    seal(GENERATED_HEADER, body)
}

/// Selection of every root (in manifest order) for a change where `head` and
/// `base` hold the file contents before and after; a path missing from `head`
/// was deleted and one missing from `base` was added.
fn selections(head: &[(&str, String)], base: &[(&str, String)]) -> Vec<RustSelection> {
    let paths: Vec<RepoPath> = head
        .iter()
        .chain(base)
        .map(|(file, _)| path(file))
        .collect();
    let changes = ChangeSet {
        paths: paths.into_iter().collect(),
        base_files: contents(base),
        head_files: contents(head),
    };
    select(&two_roots(), &changes).into_values().collect()
}

fn contents(files: &[(&str, String)]) -> BTreeMap<RepoPath, String> {
    files
        .iter()
        .map(|(file, text)| (path(file), text.clone()))
        .collect()
}

const RELEASE: &str = ".github/workflows/release.yml";
const RUST_CI: &str = ".github/workflows/rust-ci.yml";
const CACHE_TRIM: &str = ".github/workflows/rust-cache-trim.yml";
const HAND_WRITTEN: &str = ".github/workflows/lint.yml";

#[test]
fn a_change_to_a_velnor_gen_owned_workflow_selects_nothing() {
    let none = RustSelection::None;
    for file in [RELEASE, CACHE_TRIM] {
        let head = [(file, sealed("name: generated\n"))];
        assert_eq!(
            selections(&head, &[]),
            vec![none.clone(), none.clone()],
            "{file}"
        );
    }
}

#[test]
fn deleting_a_velnor_gen_owned_workflow_selects_nothing() {
    let base = [(RELEASE, sealed("name: generated\n"))];
    assert_eq!(
        selections(&[], &base),
        vec![RustSelection::None, RustSelection::None]
    );
}

#[test]
fn the_rust_ci_workflow_still_selects_everything() {
    let head = [(RUST_CI, sealed("name: Rust CI\n"))];
    assert_eq!(
        selections(&head, &[]),
        vec![
            all(AllTrigger::GeneratedWorkflow),
            all(AllTrigger::GeneratedWorkflow),
        ]
    );
}

#[test]
fn a_hand_written_workflow_still_selects_everything_as_an_unknown_path() {
    let head = [(HAND_WRITTEN, "name: Lint\n".to_string())];
    assert_eq!(
        selections(&head, &[]),
        vec![unknown(HAND_WRITTEN), unknown(HAND_WRITTEN)]
    );
}

#[test]
fn a_workflow_that_only_claims_the_generated_header_is_not_trusted() {
    let forged = sealed("name: generated\n").replace("name: generated", "name: edited");
    let head = [(RELEASE, forged)];
    assert_eq!(
        selections(&head, &[]),
        vec![unknown(RELEASE), unknown(RELEASE)]
    );
}
